mapper.select:
select FIN_CASH_INFO.CASH_ID cashId
  from FIN_CASH_INFO
 where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
   and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
   and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
   and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
   and FIN_CASH_INFO.BRANCH = 0

select t.LEV lev, t.BASE_RULE_ID baseRuleId, t.COEFFICIENT coefficient, t.SPREAD_RATE * 100 spreadRate, t.CHARGE_RATIO * 100 chargeRatio from FIN_FLOAT_CALC_RULE_DETAIL t, FIN_CASH_INFO FCI, FIN_PRODUCT FP, FIN_PRODUCT_ADD FPA where t.CASH_ID = FCI.CASH_ID and FCI.FINPROD_ID = FP.FINPROD_ID and FCI.FINPROD_ID = FPA.FINPROD_ID and FCI.CASH_TYPE_1 = #{cashType1} and FCI.CASH_TYPE_2 = #{cashType2} and FCI.BRANCH = 0 AND ((FCI.FINPROD_ID = #{finprodId}
and FPA.DEAL_MODE != #{dealMode10}
) OR (FP.P_FINPROD_ID = #{finprodId}
and FPA.DEAL_MODE = #{dealMode10}
AND FPA.TERM_TYPE != #{termType02})) and FCI.FINPROD_TYPE = #{finprodType}
and T.EFF_DATE = (select max(EFF_DATE) from FIN_FLOAT_CALC_RULE_DETAIL T1 WHERE T1.CASH_ID = t.CASH_ID AND T1.EFF_DATE >= to_date(#{effDate},'yyyy-MM-dd') AND to_date(#{sysDate},'yyyy-MM-dd') >= T1.EFF_DATE)
and (t.EFF_DATE = FP.VDATE OR FP.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
order by t.LEV

select FFCRD.LEV lev, FFCRD.BASE_RULE_ID baseRuleId, FFCRD.COEFFICIENT coefficient, FFCRD.SPREAD_RATE * 100 spreadRate, FFCRD.CHARGE_RATIO * 100 chargeRatio from FIN_FLOAT_CALC_RULE_DETAIL FFCRD, FIN_CASH_INFO FCI, FIN_PRODUCT FP, FIN_PRODUCT_ADD FPA where FFCRD.CASH_ID = FCI.CASH_ID and FCI.FINPROD_ID = FP.FINPROD_ID and FCI.FINPROD_ID = FPA.FINPROD_ID and FCI.CASH_TYPE_1 = #{cashType1} and FCI.CASH_TYPE_2 = #{cashType2} and FCI.BRANCH = 0 AND ((FCI.FINPROD_ID = #{finprodId} and FPA.DEAL_MODE != #{dealMode10}) OR (FP.P_FINPROD_ID = #{finprodId} and FPA.DEAL_MODE = #{dealMode10} AND FPA.TERM_TYPE != #{termType02}) OR (FP.FINPROD_ID = #{finprodId} and FPA.DEAL_MODE = #{dealMode10} AND FPA.TERM_TYPE = #{termType02}) ) and FCI.FINPROD_TYPE = #{finprodType}
and (FFCRD.EFF_DATE = FP.VDATE OR FP.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
order by FFCRD.LEV
